140	+// What carried turns add to every request, in bytes of text. A picture counts
141	+// as text of the tokens a provider charges for it, about one per 750 pixels.
142	+std::size_t carried_bytes(const std::vector<CarriedTurn>& turns)
143	+{
144	+    const auto picture = [](const ToolImage& image) { return std::size_t(image.width) * image.height / 750 * 4; };
145	+    std::size_t bytes = 0;
146	+    for (const CarriedTurn& turn : turns) {
147	+        for (const TurnContentPart& part : turn.user_content)
148	+            bytes += part.text.size() + part.base64.size();
149	+        for (const AgentSkillUse& skill : turn.opening_once)
150	+            bytes += skill.text.size() + (skill.picture ? picture(*skill.picture) : 0);
151	+        for (const TurnStep& step : turn.steps) {
152	+            bytes += step.assistant_turn.dump().size();
153	+            for (const TurnStepResult& result : step.results)
154	+                bytes += result.output_json.size() + (result.image ? picture(*result.image) : 0);
155	+            for (const AgentSkillUse& skill : step.once)
156	+                bytes += skill.text.size() + (skill.picture ? picture(*skill.picture) : 0);
157	+        }
158	+    }
159	+    return bytes;
160	+}
