221	+                           std::move(m_host_calls)};
222	+    finished.turns.push_back(CarriedTurn{m_transcript.user_content, m_transcript.opening_once, m_transcript.steps});
223	+    m_finished = std::move(finished);
224	+    m_carried_replay.clear();
225	+    m_host_calls.clear();
226	+}
