437	+        out += sse(json{{"type", "content_block_delta"}, {"index", 0}, {"delta", json{{"type", "signature_delta"}, {"signature", "sig"}}}});
438	+        out += sse(json{{"type", "content_block_stop"}, {"index", 0}});
439	+        out += sse(json{{"type", "content_block_start"}, {"index", 1}, {"content_block", json{{"type", "text"}, {"text", ""}}}});
440	+        out += sse(json{{"type", "content_block_delta"}, {"index", 1}, {"delta", json{{"type", "text_delta"}, {"text", text}}}});
441	+        out += sse(json{{"type", "content_block_stop"}, {"index", 1}});
442	+        if (!call_id.empty()) {
443	+            out += sse(json{{"type", "content_block_start"}, {"index", 2},
444	+                            {"content_block", json{{"type", "tool_use"}, {"id", call_id}, {"name", tool}, {"input", json::object()}}}});
