+bool same_entry(const AgentConversationContext& a, const AgentConversationContext& b)
+{
+    return a.role == b.role && a.text == b.text && a.issue_context == b.issue_context && a.call_id == b.call_id &&
+           a.tool == b.tool && a.arguments_json == b.arguments_json && a.output_json == b.output_json;
+}
+
+bool same_tools(const std::vector<OfferedTool>& a, const std::vector<OfferedTool>& b)
+{
+    return std::equal(a.begin(), a.end(), b.begin(), b.end(), [](const OfferedTool& x, const OfferedTool& y) {
+        return x.definition == y.definition && x.description == y.description;
+    });
+}
+
+// What carried turns add to every request, in bytes of text. A picture counts
+// as text of the tokens a provider charges for it, about one per 750 pixels.
+std::size_t carried_bytes(const std::vector<CarriedTurn>& turns)
+{
+    const auto picture = [](const ToolImage& image) { return std::size_t(image.width) * image.height / 750 * 4; };
+    std::size_t bytes = 0;
+    for (const CarriedTurn& turn : turns) {
+        for (const TurnContentPart& part : turn.user_content)
+            bytes += part.text.size() + part.base64.size();
+        for (const AgentSkillUse& skill : turn.opening_once)
+            bytes += skill.text.size() + (skill.picture ? picture(*skill.picture) : 0);
+        for (const TurnStep& step : turn.steps) {
+            bytes += step.assistant_turn.dump().size();
+            for (const TurnStepResult& result : step.results)
+                bytes += result.output_json.size() + (result.image ? picture(*result.image) : 0);
+            for (const AgentSkillUse& skill : step.once)
