              {"content", json::array({json{{"type", "output_text"}, {"text", reply.text}, {"annotations", json::array()}}})}}});
    if (!reply.call_id.empty())
        output.push_back(json{{"type", "function_call"}, {"id", "fc_" + id}, {"status", "completed"}, {"call_id", reply.call_id},
